@pytest.mark.parametrize("entity,kind,text,url", CASES)
def test_institution_case(entity, kind, text, url):
    matched = {m.entity_id for m in match_text(text, ENTITIES)}
    if kind == "pos":
        assert entity in matched, url
    else:
        assert entity not in matched, url


def test_every_institution_has_a_category():
    for e in ENTITIES:
        if e.kind == "institution":
            assert e.category in INSTITUTION_CATEGORIES, e.id


def test_case_entities_exist():
    ids = {e.id for e in ENTITIES}
    assert {c[0] for c in CASES} <= ids
